const mainSiteHtml = "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"theme-color\" content=\"#0c1018\"><title>KYM NOIR</title><style>:root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:#0c1018;color:#f5f4f2;font-family:system-ui,-apple-system,sans-serif}main{min-height:100vh;display:grid;place-items:center;padding:32px}.wrap{max-width:820px;width:100%}.brand{font-size:13px;letter-spacing:.35em;color:#b5a1f6;font-weight:800}.hero{font-size:clamp(64px,16vw,150px);line-height:.86;letter-spacing:-.065em;margin:28px 0 22px;font-weight:900}.muted{color:#a8a9b2;font-size:clamp(18px,3vw,24px);line-height:1.5;max-width:650px}.links{display:flex;gap:14px;flex-wrap:wrap;margin-top:38px}.btn{display:inline-block;padding:14px 18px;border:1px solid #3a3e49;border-radius:999px;text-decoration:none;color:#fff;background:#171b26}.btn:hover{border-color:#b5a1f6}.small{margin-top:50px;color:#777b86;font-size:13px}</style></head><body><main><div class=\"wrap\"><div class=\"brand\">KYM NOIR</div><div class=\"hero\">COMING<br>ALIVE.</div><p class=\"muted\">Official KYM NOIR site. Music, visuals, private projects and new work will appear here.</p><div class=\"links\"><a class=\"btn\" href=\"/projects\">Projects</a></div><div class=\"small\">Temporary launch page · editable anytime</div></div></main></body></html>";
